def positive_values(values):
    for value in values:
        if value > 0:
            yield value

def make_filter(threshold):
    def keep(value):
        return value >= threshold
    return keep

def batches(values, size):
    current = []
    for value in values:
        current.append(value)
        if len(current) == size:
            yield current
            current = []
    if current:
        yield current
